import{c as r,Z as o,Q as l,j as n,m as s,o as t}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"山坡羊·骊山怀古","description":"","frontmatter":{"title":"山坡羊·骊山怀古","author":"张养浩","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/9.md","filePath":"books/shici/yuanqu/9.md"}'),h={name:"books/shici/yuanqu/9.md"};function u(p,a,c,d,q,_){const e=o("PoemAuthor"),i=o("PoemNav");return l(),n("div",null,[a[0]||(a[0]=s('<h1 id="山坡羊·骊山怀古" tabindex="-1">山坡羊·骊山怀古 <a class="header-anchor" href="#山坡羊·骊山怀古" aria-label="Permalink to &quot;山坡羊·骊山怀古&quot;">​</a></h1><p><strong>[元] <a href="/authors/zhangyanghao.html">张养浩</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>骊山四顾，阿房一炬，当时奢侈今何处？只见草萧疏，水萦纡。</p><p>至今遗恨迷烟树。列国周齐秦汉楚。赢，都变做了土；输，都变做了土。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>骊山：在今陕西省临潼县东南，秦始皇曾在此修建阿房宫</li><li>阿房一炬：指项羽火烧阿房宫</li><li>奢侈：指秦始皇的奢华生活</li><li>萧疏：稀疏，荒凉</li><li>萦纡：曲折回环</li><li>遗恨：遗留下来的遗憾</li><li>列国周齐秦汉楚：指历史上各个朝代</li><li>赢：胜利者</li><li>输：失败者</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>在骊山四处眺望，阿房宫已被一把火烧毁，当年的奢华如今在哪里呢？只见草木稀疏荒凉，河水曲折回环。</p><p>至今遗恨还笼罩在烟雾迷蒙的树林中。历史上那些列国，周、齐、秦、汉、楚，无论是胜利者还是失败者，最终都变成了尘土。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首散曲是张养浩怀古系列作品之一，通过凭吊骊山阿房宫遗址，表达了对历史兴亡的感慨，体现了作者对人生的深刻思考。</p><p>&quot;骊山四顾，阿房一炬&quot;，开篇点明怀古的地点和对象。骊山和阿房宫，都是秦朝奢华的象征，&quot;一炬&quot;则写出了它们的毁灭。</p><p>&quot;当时奢侈今何处？只见草萧疏，水萦纡&quot;，以问句出之，表达了对历史变迁的感慨。当年的奢华已不复存在，只剩下荒草和流水。</p><p>&quot;至今遗恨迷烟树&quot;，写历史的遗恨还笼罩在烟树之中，暗示了历史的沧桑和人生的无常。</p><p>&quot;列国周齐秦汉楚&quot;，列举了历史上的各个朝代，暗示了历史的循环往复。</p><p>&quot;赢，都变做了土；输，都变做了土&quot;，是全曲的主旨所在。无论是胜利者还是失败者，最终都归于尘土。这种对历史兴亡的深刻洞察，体现了作者超脱的人生态度。</p><p>全曲语言质朴，意境深远，将历史的沧桑和人生的哲理融为一体。</p>',18)),t(e,{name:"张养浩",years:"1270年－1329年",desc:"字希孟，号云庄，元代著名散曲家。其散曲多写隐逸生活，风格清新自然，也有关心民生疾苦之作。",link:"/authors/zhangyanghao"}),t(i)])}const b=r(h,[["render",u]]);export{f as __pageData,b as default};
